package alphametics

import (
	"math/rand"
	"strings"
	"testing"
	"time"
)

func parsePuzzle(p string) (addends []string, result string, ok bool) {
	s := strings.Join(strings.Fields(p), "")
	parts := strings.Split(s, "==")
	if len(parts) != 2 {
		return nil, "", false
	}
	return strings.Split(parts[0], "+"), parts[1], true
}

func allWords(addends []string, result string) []string {
	return append(append([]string{}, addends...), result)
}

func valueOf(w string, m map[string]int) (int, bool) {
	v := 0
	for i := 0; i < len(w); i++ {
		d, ok := m[string(w[i])]
		if !ok {
			return 0, false
		}
		v = v*10 + d
	}
	return v, true
}

func validate(p string, m map[string]int) bool {
	addends, result, ok := parsePuzzle(p)
	if !ok {
		return false
	}
	letters := map[byte]bool{}
	for _, w := range allWords(addends, result) {
		for i := 0; i < len(w); i++ {
			letters[w[i]] = true
		}
	}
	if len(m) != len(letters) {
		return false
	}
	seenDigit := map[int]bool{}
	for _, d := range m {
		if d < 0 || d > 9 || seenDigit[d] {
			return false
		}
		seenDigit[d] = true
	}
	for _, w := range allWords(addends, result) {
		if len(w) > 1 && m[string(w[0])] == 0 {
			return false
		}
	}
	sum := 0
	for _, w := range addends {
		v, ok := valueOf(w, m)
		if !ok {
			return false
		}
		sum += v
	}
	rv, ok := valueOf(result, m)
	return ok && sum == rv
}

func bruteSolve(p string) (map[string]int, bool) {
	addends, result, ok := parsePuzzle(p)
	if !ok {
		return nil, false
	}
	var letters []byte
	seen := map[byte]bool{}
	for _, w := range allWords(addends, result) {
		for i := 0; i < len(w); i++ {
			if !seen[w[i]] {
				seen[w[i]] = true
				letters = append(letters, w[i])
			}
		}
	}
	if len(letters) > 7 {
		return nil, false
	}
	m := map[string]int{}
	var used [10]bool
	var rec func(k int) bool
	rec = func(k int) bool {
		if k == len(letters) {
			return validate(p, m)
		}
		for d := 0; d <= 9; d++ {
			if used[d] {
				continue
			}
			used[d] = true
			m[string(letters[k])] = d
			if rec(k + 1) {
				return true
			}
			delete(m, string(letters[k]))
			used[d] = false
		}
		return false
	}
	if rec(0) {
		out := map[string]int{}
		for k, v := range m {
			out[k] = v
		}
		return out, true
	}
	return nil, false
}

func check(t *testing.T, p string) {
	t.Helper()
	sol, err := Solve(p)
	if err == nil {
		if !validate(p, sol) {
