		}
	}
	_, want := bruteSolve(p)
	if want != (err == nil) {
		t.Fatalf("Solve(%q) solvable=%v, brute force solvable=%v (err=%v, sol=%#v)", p, err == nil, want, err, sol)
	}
}

func TestFixedEdges(t *testing.T) {
	cases := []string{
